-- MySQL 8.4 parity coverage: every statement below returns the same result on MySQL 8.4.9.
drop database if exists cov_dt;
create database cov_dt;
use cov_dt;
select date_add('2024-01-31', interval 1 month), date_add('2024-02-29', interval 1 year), date_sub('2024-03-31', interval 1 month);
select date_add('2024-01-01', interval '1:2' hour_minute), date_add('2024-01-01', interval '1 2' day_hour), date_add('2024-01-01 00:00:00', interval '1.5' second);
select date_add('2024-01-01', interval -1 day), adddate('2024-01-01', 31), subdate('2024-01-01', 1);
select datediff('2024-03-01','2024-02-01'), datediff('2024-01-01 23:59:59','2024-01-02'), timediff('10:00:00','12:30:00'), timediff('2024-01-02 00:00:00','2024-01-01 00:00:00');
select timestampdiff(month,'2024-01-31','2024-02-29'), timestampdiff(year,'2000-02-29','2001-02-28'), timestampdiff(second,'2024-01-01','2024-01-02'), timestampdiff(quarter, '2024-01-01','2024-12-31');
select last_day('2024-02-10'), last_day('2023-02-10'), last_day('2024-13-01'), dayofyear('2024-12-31'), week('2024-01-01'), week('2024-01-01',1), week('2024-12-31',3), yearweek('2024-12-31');
select weekday('2024-01-01'), dayofweek('2024-01-01'), dayname('2024-01-01'), monthname('2024-01-01'), quarter('2024-05-01');
select str_to_date('2024-01-15','%Y-%m-%d'), str_to_date('15/01/2024','%d/%m/%Y'), str_to_date('Jan 15 2024','%b %d %Y'), str_to_date('abc','%Y'), str_to_date('2024-02-30','%Y-%m-%d');
select str_to_date('10:20:30','%H:%i:%s'), str_to_date('10:20:30 PM','%h:%i:%s %p'), str_to_date('2024','%Y'), str_to_date('202401','%Y%m');
select date_format('2024-01-05 13:04:05.123456','%a %b %c %D %e %f %H %h %I %i %j %k %l %M %p %r %S %s %T %U %u %V %v %W %w %X %x %y %%');
select date_format('2024-01-05','%Q'), date_format(NULL,'%Y'), time_format('25:30:00','%H %k %h %l'), time_format('-01:00:00','%H');
select makedate(2024, 60), makedate(2024, 0), maketime(12, 30, 45.5), maketime(-1, 0, 0), sec_to_time(3661), sec_to_time(-1), time_to_sec('-01:00:00');
select from_days(738000), to_days('2024-01-01'), to_seconds('2024-01-01');
select period_add(202401, 13), period_diff(202401, 202312), period_add(0, 1);
select extract(year_month from '2024-05-06'), extract(day_microsecond from '2024-05-06 01:02:03.5'), extract(week from '2024-05-06');
select cast('2024-1-1' as date), cast('24-01-01' as date), cast('20240101' as date), cast('2024/01/01' as date), cast('2024-01-01T10:00:00' as datetime);
select cast('0000-00-00' as date), cast('2024-00-01' as date), cast('2024-02-30' as date);
select date('2024-01-01 23:59:59.999'), time('2024-01-01 23:59:59.999'), year('2024-01-01'), hour('100:00:00'), minute('10:61:00');
select timestamp('2024-01-01'), timestamp('2024-01-01','12:00:00'), timestampadd(month, 1, '2024-01-31'), timestampadd(microsecond, 1, '2024-01-01');
select date '2024-01-01' + interval 1 day, '2024-01-01' + interval 1 day, interval 1 day + '2024-01-01';
select date '2024-01-01' - date '2023-01-01', datetime'2024-01-01 00:00:00' + 0, time'10:00:00' + 0, date'2024-01-01' + 0;
select str_to_date('2024-01-01 10:00:00.123','%Y-%m-%d %H:%i:%s.%f'), get_format(date,'usa'), get_format(datetime,'iso');
select dayofmonth('2024-00-00'), month('2024-00-00'), dayname('0000-00-00');
select utc_date() = curdate() or 1, sysdate() is not null, localtime() is not null, current_timestamp(3) is not null;
select '2024-01-01' < '2024-1-2', date'2024-01-01' < '2024-1-2', cast('2024-01-01' as date) = '2024-01-01 00:00:00';
select timestampdiff(day, '2024-01-01 12:00', '2024-01-02 11:59'), datediff('2024-01-02 11:59', '2024-01-01 12:00');
select time(cast('2024-01-01 10:20:30.456' as datetime(3))), cast(time'10:20:30.4567' as time(2));
select date_format('2024-01-01', '%W %M %Y'), date_format('2024-01-01 00:00:00', '%l %p');
select week('2024-12-29', 0), week('2024-12-29', 2), week('2024-12-29', 4), week('2024-12-29', 5), week('2024-12-29', 6), week('2024-12-29', 7);
drop database cov_dt;
